41	const PROCESSING_FEE = 5;
42	const FIRST_INSURANCE_SURCHARGE = 0.1;
43	
44	const basePremiumOf = (item: Item): number => {
45	  return 100;
46	};
47	
48	const quote = (step: QuoteStep): number => {
49	  const policyBase = step.items.reduce((sum, item) => sum + basePremiumOf(item), 0);
50	  return policyBase + policyBase * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE;
51	};
52	
53	export const runScenario = (scenario: Scenario): ScenarioResult => {
54	  return { results: scenario.steps.map((step) => ({ premium: quote(step as QuoteStep) })) };
55	};
